fn step(&self, cx: &Context<'_>) -> bool {
    let before = self.0.load(Ordering::Relaxed);
    if before.checked_sub(1).is_some_and(|after| {
        self.0
            .compare_exchange(before, after, Ordering::Relaxed, Ordering::Relaxed)
            .is_ok()
    }) {
        true
    } else {
        cx.waker().wake_by_ref();
        false
    }
}
